  // src/js/darkMode.js
  function initDarkMode() {
    const darkModeToggle = document.getElementById("darkModeToggle");
    if (darkModeToggle) {
      darkModeToggle.style.display = "none";
    }
    localStorage.removeItem(CONFIG.UI.THEME_KEY);
    document.documentElement.classList.add("dark");
    document.documentElement.classList.remove("light");
  }

  // src/js/smoothScroll.js
  function initSmoothScroll() {
    document.body.classList.add("fade-in");
    function handleSmoothScroll(href) {
      const targetElement = document.querySelector(href);
      if (targetElement) {
        const headerOffset = document.getElementById("mainHeader")?.offsetHeight || 80;
        const elementPosition = targetElement.getBoundingClientRect().top;
        const offsetPosition = elementPosition + window.pageYOffset - headerOffset;
        window.scrollTo({
          top: offsetPosition,
          behavior: "smooth"
        });
      }
    }
    function handlePageTransition(href, isInternalLink) {
      document.body.classList.add("fade-out");
      setTimeout(() => {
        if (isInternalLink) {
          handleSmoothScroll(href);
          setTimeout(() => {
            document.body.classList.remove("fade-out");
          }, 50);
        } else {
          window.location.href = href;
        }
      }, 300);
    }
    document.querySelectorAll(
      'a:not([href^="tel:"]):not([href^="mailto:"]):not(.social-share-btn):not(.modal-contact-button):not([target="_blank"])'
    ).forEach((link) => {
      link.addEventListener("click", function(e) {
        const href = this.getAttribute("href");
        if (!href || href === "#") {
          return;
        }
        const isInternalAnchor = href.startsWith("#");
        const isSamePage = isInternalAnchor || href.split("#")[0] === window.location.pathname.split("/").pop() || href.split("#")[0] === "";
        if (this.hostname === window.location.hostname || href.startsWith("/")) {
          e.preventDefault();
          handlePageTransition(href, isInternalAnchor && isSamePage);
        }
      });
    });
  }

  // src/js/sectionStyler.js
  function applyAlternatingGradients(containerSelector, gradientClasses) {
    if (gradientClasses.length < 2) {
      console.error(
        "Se necesitan al menos dos clases de gradiente para alternar."
      );
      return;
    }
    const container = document.querySelector(containerSelector);
    if (!container) {
      return;
    }
    const sections = container.querySelectorAll("section");
    sections.forEach((section, index) => {
      section.classList.remove(...gradientClasses);
      const classToAdd = gradientClasses[index % 2];
      section.classList.add(classToAdd);
    });
  }

  // src/js/scrollAnimations.js
  var observer = typeof IntersectionObserver !== "undefined" ? new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-visible");
          observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.1 }
  ) : null;
  function observeAnimatedElements(elements) {
    if (!observer || !elements) return;
    const elementsToObserve = elements instanceof NodeList ? Array.from(elements) : [elements];
    elementsToObserve.forEach((el, index) => {
      if (el.classList.contains("scroll-animate-initial")) {
        el.style.transitionDelay = `${30 * index}ms`;
        observer.observe(el);
      }
    });
  }
  function initScrollAnimations() {
    const animatedElements = document.querySelectorAll(".scroll-animate-initial");
    if (animatedElements.length > 0) {
      observeAnimatedElements(animatedElements);
    }
  }

  // src/js/nav.js
  var toggleAria = (element, attr, value) => {
    if (element) element.setAttribute(attr, value);
  };
  function initMobileMenu() {
    const mobileMenuButton = document.getElementById("mobileMenuButton");
    const mobileMenu = document.getElementById("mobileMenu");
    const closeMobileMenuBtn = document.getElementById("closeMobileMenu");
    const overlay = document.getElementById("nav-overlay");
    if (!mobileMenuButton || !mobileMenu || !overlay) return;
    mobileMenu.inert = true;
    mobileMenu.style.visibility = "hidden";
    const setMenuState = (isOpen) => {
      const toggleMenuClasses = () => {
        mobileMenu.classList.toggle("mobile-menu-active", isOpen);
        mobileMenu.classList.toggle("translate-x-full", !isOpen);
        mobileMenu.classList.toggle("pointer-events-none", !isOpen);
        overlay.classList.toggle("opacity-0", !isOpen);
        overlay.classList.toggle("pointer-events-none", !isOpen);
        mobileMenuButton.classList.toggle("is-active", isOpen);
        toggleAria(mobileMenuButton, "aria-expanded", isOpen);
        toggleAria(mobileMenu, "aria-hidden", !isOpen);
        mobileMenu.inert = !isOpen;
      };
      if (isOpen) {
        overlay.classList.remove("hidden");
        document.body.classList.add("menu-open");
        document.documentElement.classList.add("menu-open");
        requestAnimationFrame(() => {
          mobileMenu.style.visibility = "visible";
          toggleMenuClasses();
        });
      } else {
        toggleMenuClasses();
        setTimeout(() => {
          if (!mobileMenu.classList.contains("mobile-menu-active")) {
            mobileMenu.style.visibility = "hidden";
            overlay.classList.add("hidden");
            document.body.classList.remove("menu-open");
            document.documentElement.classList.remove("menu-open");
          }
        }, 500);
      }
    };
    const openMobileMenu = () => setMenuState(true);
    const closeMobileMenu = () => setMenuState(false);
    mobileMenuButton.addEventListener("click", (e) => {
      e.stopPropagation();
      const isOpen = mobileMenu.classList.contains("mobile-menu-active");
      if (isOpen) closeMobileMenu();
      else openMobileMenu();
    });
    if (closeMobileMenuBtn) {
      closeMobileMenuBtn.addEventListener("click", closeMobileMenu);
    }
    overlay.addEventListener("click", closeMobileMenu);
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && mobileMenu.classList.contains("mobile-menu-active")) {
        closeMobileMenu();
      }
    });
    mobileMenu.addEventListener("click", (e) => {
      const link = e.target.closest("a");
      if (!link) return;
      if (e.target.closest("#mobileServicesButton")) return;
      closeMobileMenu();
    });
  }
  function initMobileServicesMenu() {
    const mobileServicesButton = document.getElementById("mobileServicesButton");
    const mobileServicesMenu = document.getElementById("mobileServicesMenu");
    if (!mobileServicesButton || !mobileServicesMenu) return;
    mobileServicesButton.addEventListener("click", (e) => {
      e.stopPropagation();
      const isActive = mobileServicesMenu.classList.toggle("is-active");
      toggleAria(mobileServicesButton, "aria-expanded", isActive);
      const icon = mobileServicesButton.querySelector("i.fa-chevron-down");
      if (icon) {
        icon.classList.toggle("rotate-180");
      }
    });
  }
  function initScrollSpy() {
    const sections = document.querySelectorAll("section[id]");
    const desktopLinks = document.querySelectorAll("header nav a");
    const mobileLinks = document.querySelectorAll(".mobile-menu-link");
    if (sections.length === 0 && desktopLinks.length === 0) return;
    const currentPath = window.location.pathname;
    mobileLinks.forEach((link) => {
      const href = link.getAttribute("href");
      if (href === currentPath || currentPath === "/" && href === "/index.html") {
        link.classList.add("mobile-link-active");
      } else {
        link.classList.remove("mobile-link-active");
      }
    });
    if (sections.length === 0) return;
    const observerOptions = {
      root: null,
      rootMargin: "0px 0px -60% 0px",
      threshold: 0
    };
    const sectionObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const sectionId = entry.target.id;
          desktopLinks.forEach((link) => {
            link.classList.remove("nav-active");
            if (link.getAttribute("href") === `#${sectionId}`) {
              link.classList.add("nav-active");
            }
          });
          mobileLinks.forEach((link) => {
            if (link.getAttribute("href") === `#${sectionId}`) {
              link.classList.add("mobile-link-active");
            } else if (link.getAttribute("href")?.startsWith("#")) {
              link.classList.remove("mobile-link-active");
            }
          });
        }
      });
    }, observerOptions);
    sections.forEach((section) => {
      sectionObserver.observe(section);
    });
  }
  function initDesktopServicesMenu() {
    const servicesMenuGroup = document.getElementById("services-menu-group");
    const servicesMenuDropdown = document.getElementById(
      "services-menu-dropdown"
    );
    let timeoutId;
    if (!servicesMenuGroup || !servicesMenuDropdown) return;
    servicesMenuGroup.addEventListener("mouseenter", () => {
      clearTimeout(timeoutId);
      servicesMenuDropdown.classList.remove("hidden");
    });
    servicesMenuGroup.addEventListener("mouseleave", () => {
      timeoutId = setTimeout(() => {
        servicesMenuDropdown.classList.add("hidden");
      }, 300);
    });
  }
  function initStickyHeader() {
    const header = document.querySelector(".sticky-header");
    if (!header) return;
    const handleScroll = () => {
      if (window.scrollY > 20) {
        header.classList.add("header-scrolled");
      } else {
        header.classList.remove("header-scrolled");
      }
    };
    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
  }
  function initNav() {
    initMobileMenu();
    initMobileServicesMenu();
    initScrollSpy();
    initDesktopServicesMenu();
    initStickyHeader();
  }

