  // src/js/portfolioCards.js
  function createSrcSet(srcset) {
    if (!srcset) return "";
    return Object.entries(srcset).map(([size, url]) => `${url} ${size}`).join(", ");
  }
  function createCardImage(item, srcsetAttr, sizesAttr, priority) {
    return `
    <div class="relative">
      <img
        class="w-full h-56 object-cover group-hover:scale-105 transition-transform duration-500 ease-in-out"
        ${srcsetAttr}
        ${sizesAttr}
        src="${item.imgSrc}"
        alt="${item.imgAlt}"
        width="400"
        height="224"
        ${priority ? 'loading="eager" fetchpriority="high"' : 'loading="lazy"'}
        decoding="async"
      />
      ${item.tourType ? `
        <div class="absolute top-2 right-2 flex items-center space-x-1.5 rounded-full bg-black/50 px-3 py-1 text-xs font-semibold text-white backdrop-blur-sm">
          <i class="fas fa-vr-cardboard"></i>
          <span>${item.tourType}</span>
        </div>
      ` : ""}
    </div>
  `;
  }
  function createCardContent(item) {
    return `
    <div class="p-6">
      <div class="flex items-center gap-2 mb-2">
        <h3 class="text-xl font-semibold text-gray-900 dark:text-white">${item.title}</h3>
        ${item.isNew ? `
          <span class="bg-primary-blue dark:bg-primary-green text-white text-xs font-bold uppercase py-1 px-2 rounded-full">
            Nuevo
          </span>
        ` : ""}
      </div>
      <p class="text-sm text-primary-blue dark:text-primary-green mb-2">${item.tags}</p>
      <p class="text-gray-600 dark:text-gray-400 text-base">${item.description}</p>
    </div>
  `;
  }
  function createPortfolioCard(item, priority = false) {
    const isLink = item.type === "link";
    const tag = isLink ? "a" : "div";
    const hrefAttr = isLink ? `href="${item.url}" target="_blank" rel="noopener noreferrer"` : "";
    const cursorClass = "cursor-pointer";
    const idAttr = item.type === "modal" ? `id="card-proyecto-${item.id}"` : "";
    const dataTypeAttr = item.type === "modal" ? 'data-type="modal"' : "";
    const srcsetAttr = item.imgSrcSet ? `srcset="${createSrcSet(item.imgSrcSet)}"` : "";
    const sizesAttr = item.imgSrcSet ? `sizes="(max-width: 767px) 100vw, (max-width: 1023px) 50vw, 400px"` : "";
    return `
    <${tag} ${idAttr} ${dataTypeAttr} class="portfolio-item group scroll-animate-initial ${cursorClass}" data-category="${item.category}" ${hrefAttr}>
      <div class="absolute inset-0 bg-gradient-to-br from-primary-blue/10 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none z-10"></div>
      ${createCardImage(item, srcsetAttr, sizesAttr, priority)}
      ${createCardContent(item)}
    </${tag}>
  `;
  }
  function renderPortfolioHtml({ limit = null, priority = false } = {}) {
    const items = limit ? portfolioData.slice(0, limit) : portfolioData;
    return items.map((item, i) => createPortfolioCard(item, priority && i === 0)).join("");
  }

  // src/js/componentLoader.js
  var APP_VERSION = CONFIG.UI.APP_VERSION || "1.0.0";
  var interpolateTemplate = (html, dataset) => {
    let processedHtml = html;
    for (const key in dataset) {
      if (key === "component" || key === "heroCustomStyles") continue;
      const placeholder = `{{${key.replace(/([A-Z])/g, "_$1").replace("-", "_").toUpperCase()}}}`;
      const value = dataset[key];
      if (value !== void 0) {
        processedHtml = processedHtml.replaceAll(placeholder, value);
      }
    }
    return processedHtml.replace(/\{\{[A-Z_]+\}\}/g, "");
  };
  var fetchComponent = async (url) => {
    const versionedUrl = `${url}?v=${APP_VERSION}`;
    const response = await fetch(versionedUrl);
    if (!response.ok) throw new Error(`HTTP Error: ${response.statusText}`);
    return await response.text();
  };
  var loadStaticComponent = async (selector, url) => {
    try {
      const html = await fetchComponent(url);
      const element = document.querySelector(selector);
      if (element) element.innerHTML = html;
    } catch (error) {
      console.error(`[ComponentLoader] Fallo al cargar est\xE1tico ${url}:`, error);
    }
  };
  var loadConfigurableComponent = async (element) => {
    const componentName = element.dataset.component;
    if (!componentName) return;
    const url = `/components/${componentName}.html`;
    try {
      if (element.dataset.heroCustomStyles) {
        const style = document.createElement("style");
        style.textContent = element.dataset.heroCustomStyles;
        document.head.appendChild(style);
      }
      const rawHtml = await fetchComponent(url);
      element.innerHTML = interpolateTemplate(rawHtml, element.dataset);
    } catch (error) {
      console.error(`[ComponentLoader] Fallo al cargar configurable ${url}:`, error);
    }
  };
  var loadComponents = async () => {
    const staticTargets = [
      { selector: "#nav-placeholder", url: "/components/nav.html" },
      { selector: "#footer-placeholder", url: "/components/footer.html" },
      { selector: "#cookie-banner-placeholder", url: "/components/cookie-banner.html" }
    ];
    const staticPromises = staticTargets.map((t) => loadStaticComponent(t.selector, t.url));
    const configurableElements = document.querySelectorAll("[data-component]");
    const configurablePromises = Array.from(configurableElements).map(loadConfigurableComponent);
    await Promise.all([...staticPromises, ...configurablePromises]);
  };

