  // src/js/breadcrumbs.js
  var BREADCRUMB_NAMES = {
    "/": "Inicio",
    "blog.html": "Blog",
    "proyectos.html": "Proyectos",
    "agencia-automatizaciones.html": "Automatizaciones",
    "agencia-desarrollo-web-con-codigo.html": "Desarrollo a Medida",
    "agencia-seo-local.html": "SEO Local",
    "agencia-seo.html": "SEO General"
  };
  function generateBreadcrumbs(placeholderSelector) {
    const placeholder = document.querySelector(placeholderSelector);
    if (!placeholder) {
      return;
    }
    const path = window.location.pathname;
    const pageFileName = path.substring(path.lastIndexOf("/") + 1) || "index.html";
    let crumbs = [{ name: BREADCRUMB_NAMES["/"], url: "/" }];
    if (pageFileName.startsWith("articulo-")) {
      crumbs.push({ name: BREADCRUMB_NAMES["blog.html"], url: "/blog.html" });
      const customTitle = placeholder.getAttribute("data-breadcrumb") || placeholder.closest("[data-breadcrumb]")?.getAttribute("data-breadcrumb");
      const articleTitle = customTitle || document.querySelector("h1")?.textContent.trim();
      if (articleTitle) {
        crumbs.push({ name: articleTitle });
      }
    } else if (BREADCRUMB_NAMES[pageFileName] && pageFileName !== "index.html") {
      crumbs.push({ name: BREADCRUMB_NAMES[pageFileName] });
    }
    if (crumbs.length <= 1) {
      return;
    }
    const breadcrumbsHtml = `
    <nav aria-label="Breadcrumb" class="breadcrumb-nav">
      <ol class="flex items-center space-x-2 text-sm">
        ${crumbs.map((crumb, index) => {
      const isLast = index === crumbs.length - 1;
      if (isLast) {
        return `<li><span class="font-medium text-gray-500 dark:text-gray-400" aria-current="page">${crumb.name}</span></li>`;
      } else {
        return `
                <li class="flex items-center">
                  <a href="${crumb.url}" class="text-primary-blue dark:text-primary-green hover:underline">${crumb.name}</a>
                  <span class="mx-2 text-gray-400 dark:text-gray-500" aria-hidden="true">/</span>
                </li>
              `;
      }
    }).join("")}
      </ol>
    </nav>
  `;
    placeholder.innerHTML = breadcrumbsHtml;
  }

  // src/js/contactForm.js
  function isHoneypotTriggered(formData) {
    const honeypotValue = formData.get("b_website");
    return typeof honeypotValue === "string" && honeypotValue.trim().length > 0;
  }
  function containsSpamPatterns(text) {
    if (!text || typeof text !== "string") return false;
    const cyrillicRegex = /[\u0400-\u04FF]/;
    const cjkRegex = /[\u4E00-\u9FFF]/;
    if (cyrillicRegex.test(text) || cjkRegex.test(text)) {
      return true;
    }
    const linkCount = (text.match(/https?:\/\//gi) || []).length;
    return linkCount > 2;
  }
  function isSubmittedTooFast(renderTimestamp, minSeconds = 3) {
    if (!renderTimestamp) return false;
    const elapsedSeconds = (Date.now() - renderTimestamp) / 1e3;
    return elapsedSeconds < minSeconds;
  }
  function isBotSubmission(formData, renderTimestamp, minSeconds = 3) {
    if (isHoneypotTriggered(formData)) return true;
    if (isSubmittedTooFast(renderTimestamp, minSeconds)) return true;
    const name = formData.get("name");
    const message = formData.get("message");
    if (typeof name === "string" && containsSpamPatterns(name)) return true;
    if (typeof message === "string" && containsSpamPatterns(message)) return true;
    return false;
  }
  async function sendContactFormData(actionUrl, formData) {
    const response = await fetch(actionUrl, {
      method: "POST",
      body: formData,
      headers: { Accept: "application/json" }
    });
    return response.ok;
  }
